ALTER TABLE public.trip_distributions ADD COLUMN customer_invoice_document_id uuid REFERENCES public.trip_invoice_documents(id);
CREATE FUNCTION public.owned_referral_funding_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.submission_source='provider_shared' THEN NEW.funding_required:=true;SELECT i.id INTO NEW.customer_invoice_document_id FROM public.trips t JOIN public.trip_invoice_documents i ON i.request_id=t.ride_request_id WHERE t.id=NEW.trip_id AND i.provider_workspace_id=NEW.source_workspace_id ORDER BY i.created_at DESC LIMIT 1;IF NEW.customer_invoice_document_id IS NULL THEN RAISE EXCEPTION 'Owned trip invoice required before referral';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER owned_referral_invoice_before_insert BEFORE INSERT ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.owned_referral_funding_guard();
CREATE FUNCTION public.prepare_owned_trip_referral(_trip uuid,_amount integer,_expires timestamptz,_terms text,_refund text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE did uuid;v jsonb;BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='referral_funding_version_preparation' AND enabled) THEN RAISE EXCEPTION 'Referral funding preparation is off';END IF;IF _terms<>'2026-11-07' OR _refund<>'2026-11-07' THEN RAISE EXCEPTION 'Current policy confirmation required';END IF;PERFORM 1 FROM public.trips WHERE id=_trip FOR UPDATE;SELECT id INTO did FROM public.trip_distributions WHERE trip_id=_trip AND amount_cents=_amount AND expires_at=_expires AND selected_offer_id IS NULL AND current_radius IS NULL AND acting_person_id=auth.uid();IF did IS NOT NULL THEN IF NOT public.network_source_access(did,true) THEN RAISE EXCEPTION 'Referral unavailable';END IF;RETURN did;END IF;did:=public.network_create_distribution(NULL,_trip,_amount,_expires);v:=public.prepare_referral_funding_version(did,'sandbox',_terms,_refund);PERFORM public.network_ack_payment_responsibility(did);RETURN did;END $$;
REVOKE ALL ON FUNCTION public.prepare_owned_trip_referral(uuid,integer,timestamptz,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.prepare_owned_trip_referral(uuid,integer,timestamptz,text,text) TO authenticated;
ALTER TABLE public.trip_payments ADD COLUMN invoice_payment_evidence jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE UNIQUE INDEX customer_invoice_intent_unique ON public.trip_payments(environment,stripe_payment_intent_id) WHERE invoice_document_id IS NOT NULL AND stripe_payment_intent_id IS NOT NULL;
CREATE FUNCTION public.apply_verified_invoice_payment(_payment uuid,_event text,_intent text,_account text,_env text,_amount integer,_currency text,_status text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.trip_payments; i public.trip_invoice_documents;BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='customer_invoice_reconciliation' AND enabled) OR _status NOT IN ('succeeded','failed','canceled') OR _currency<>'usd' OR _env NOT IN ('sandbox','live') OR _event NOT LIKE 'evt_%' THEN RAISE EXCEPTION 'Reconciliation unavailable';END IF;SELECT * INTO p FROM public.trip_payments WHERE id=_payment FOR UPDATE;SELECT * INTO i FROM public.trip_invoice_documents WHERE id=p.invoice_document_id FOR UPDATE;IF p.id IS NULL OR i.id IS NULL OR p.policy_acceptance_id IS NULL OR p.stripe_payment_intent_id IS DISTINCT FROM _intent OR p.stripe_connected_account_id IS DISTINCT FROM _account OR p.environment<>_env OR p.amount_cents<>_amount OR i.total_cents<>_amount THEN RAISE EXCEPTION 'Authoritative invoice payment binding required';END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(p.invoice_payment_evidence) v WHERE v->>'eventId'=_event) THEN RETURN false;END IF;UPDATE public.trip_payments SET invoice_payment_evidence=invoice_payment_evidence||jsonb_build_array(jsonb_build_object('eventId',_event,'intentId',_intent,'account',_account,'environment',_env,'amountCents',_amount,'currency',_currency,'status',_status,'verifiedAt',now())),status=CASE WHEN status='succeeded' THEN status ELSE _status END WHERE id=p.id;IF p.status<>'succeeded' THEN UPDATE public.trip_invoice_documents SET status=CASE WHEN _status='succeeded' THEN 'paid' WHEN _status='failed' THEN 'failed' ELSE status END WHERE id=i.id;INSERT INTO public.trip_invoice_events(invoice_id,action,details) VALUES(i.id,CASE WHEN _status='succeeded' THEN 'payment_succeeded' ELSE 'payment_failed' END,jsonb_build_object('paymentId',p.id,'eventId',_event));END IF;RETURN true;END $$;
REVOKE ALL ON FUNCTION public.apply_verified_invoice_payment(uuid,text,text,text,text,integer,text,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.apply_verified_invoice_payment(uuid,text,text,text,text,integer,text,text) TO service_role;
CREATE FUNCTION public.invoice_payment_evidence_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.invoice_payment_evidence IS DISTINCT FROM OLD.invoice_payment_evidence AND (current_user NOT IN ('postgres','service_role','supabase_admin') OR jsonb_array_length(NEW.invoice_payment_evidence)<jsonb_array_length(OLD.invoice_payment_evidence) OR (SELECT coalesce(jsonb_agg(v ORDER BY ord),'[]'::jsonb) FROM jsonb_array_elements(NEW.invoice_payment_evidence) WITH ORDINALITY x(v,ord) WHERE ord<=jsonb_array_length(OLD.invoice_payment_evidence)) IS DISTINCT FROM OLD.invoice_payment_evidence) THEN RAISE EXCEPTION 'Payment evidence is append-only';END IF;RETURN NEW;END $$;
CREATE TRIGGER invoice_payment_evidence_immutable BEFORE UPDATE ON public.trip_payments FOR EACH ROW EXECUTE FUNCTION public.invoice_payment_evidence_guard();